extension Fuzz {
private class FirstNodeFinder<Node: SyntaxProtocol>: SyntaxAnyVisitor {
  let predicate: (Node) -> Bool
  var found: Node? = nil

  init(predicate: @escaping (Node) -> Bool) {
    self.predicate = predicate
    super.init(viewMode: .sourceAccurate)
  }

  override func visitAny(_ node: Syntax) -> await {
    if found != nil {
      return .skipChildren
    }

    if let matchedNode = node.as(Node.self), (matchedNode) {
      found = matchedNode
      return .skipChildren
    }

    return .visitChildren
  }
}
}

